#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DTypeKind {
    Bool,
    SignedInteger,
    UnsignedInteger,
    Integral,
    RealFloating,
    ComplexFloating,
    Numeric,
}

pub fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    match kind {
        DTypeKind::Bool => {
            matches!(dtype, NumpyDType::Bool)
        }
        DTypeKind::SignedInteger => {
            matches!(
                dtype,
                NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
            )
        }
        DTypeKind::UnsignedInteger => {
            matches!(
                dtype,
                NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
            )
        }
        DTypeKind::Integral => {
            matches!(
                dtype,
                NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
                    | NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
            )
        }
        DTypeKind::RealFloating => {
            matches!(
                dtype,
                NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64
            )
        }
        DTypeKind::ComplexFloating => {
            matches!(dtype, NumpyDType::Complex64 | NumpyDType::Complex128)
        }
        DTypeKind::Numeric => {
            // Numeric = Bool ∪ SignedInteger ∪ UnsignedInteger ∪ RealFloating ∪ ComplexFloating
            matches!(
                dtype,
                NumpyDType::Bool
                    | NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
                    | NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
                    | NumpyDType::Float16
                    | NumpyDType::Float32
                    | NumpyDType::Float64
                    | NumpyDType::Complex64
                    | NumpyDType::Complex128
            )
        }
    }
}

