    use super::*;

    #[test]
    fn test_bool() {
        assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Bool));
        assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Numeric));
        assert!(!numpy_isdtype(NumpyDType::Bool, DTypeKind::Integral));
    }

    #[test]
    fn test_signed_integer() {
        for &dt in &[
            NumpyDType::Int8,
            NumpyDType::Int16,
            NumpyDType::Int32,
            NumpyDType::Int64,
        ] {
            assert!(numpy_isdtype(dt, DTypeKind::SignedInteger));
            assert!(numpy_isdtype(dt, DTypeKind::Integral));
            assert!(numpy_isdtype(dt, DTypeKind::Numeric));
            assert!(!numpy_isdtype(dt, DTypeKind::Bool));
            assert!(!numpy_isdtype(dt, DTypeKind::RealFloating));
        }
    }

    #[test]
    fn test_unsigned_integer() {
        for &dt in &[
            NumpyDType::UInt8,
            NumpyDType::UInt16,
            NumpyDType::UInt32,
            NumpyDType::UInt64,
        ] {
            assert!(numpy_isdtype(dt, DTypeKind::UnsignedInteger));
            assert!(numpy_isdtype(dt, DTypeKind::Integral));
            assert!(numpy_isdtype(dt, DTypeKind::Numeric));
            assert!(!numpy_isdtype(dt, DTypeKind::Bool));
            assert!(!numpy_isdtype(dt, DTypeKind::RealFloating));
        }
    }

    #[test]
    fn test_real_floating() {
        for &dt in &[NumpyDType::Float16, NumpyDType::Float32, NumpyDType::Float64] {
            assert!(numpy_isdtype(dt, DTypeKind::RealFloating));
            assert!(numpy_isdtype(dt, DTypeKind::Numeric));
            assert!(!numpy_isdtype(dt, DTypeKind::Integral));
        }
    }

    #[test]
    fn test_complex_floating() {
        for &dt in &[NumpyDType::Complex64, NumpyDType::Complex128] {
            assert!(numpy_isdtype(dt, DTypeKind::ComplexFloating));
            assert!(numpy_isdtype(dt, DTypeKind::Numeric));
            assert!(!numpy_isdtype(dt, DTypeKind::RealFloating));
        }
    }
